const SUPPORTED_UI_LANGUAGES = Object.freeze(Object.keys(UI_PACKS));
let currentUiLanguage = "en";

function resolveUiLanguage(language) {
  const requested = String(language || "auto").trim().toLowerCase();
  const candidates = requested === "auto"
    ? [...(navigator.languages || []), navigator.language || ""]
    : [requested];
  for (const candidate of candidates) {
    const normalized = String(candidate || "").toLowerCase();
    if (SUPPORTED_UI_LANGUAGES.includes(normalized)) return normalized;
    const base = normalized.split("-")[0];
    if (SUPPORTED_UI_LANGUAGES.includes(base)) return base;
  }
  return "en";
}

function tr(key, variables = {}) {
  const pack = UI_PACKS[currentUiLanguage] || UI_PACKS.en;
  let value = pack[key] || UI_PACKS.en[key] || key;
  Object.entries(variables).forEach(([name, replacement]) => {
    value = value.split(`{${name}}`).join(String(replacement));
  });
  return value;
}

function trForLanguage(language, key, variables = {}) {
  const normalized = String(language || "").trim().toLowerCase().split("-")[0];
  const pack = UI_PACKS[normalized] || CONTENT_LANGUAGE_PACKS[normalized] || UI_PACKS[currentUiLanguage] || UI_PACKS.en;
  let value = pack[key] || UI_PACKS.en[key] || key;
  Object.entries(variables).forEach(([name, replacement]) => {
    value = value.split(`{${name}}`).join(String(replacement));
  });
  return value;
}

function setNodeHtml(selector, key) {
  const node = document.querySelector(selector);
  if (node) node.innerHTML = tr(key);
}

function setNodeText(selector, key) {
  const node = document.querySelector(selector);
  if (node) node.textContent = tr(key);
}

function setLabelLead(selector, key) {
  const label = document.querySelector(selector);
  if (!label) return;
  const textNode = [...label.childNodes].find((node) => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
  if (textNode) textNode.textContent = `${tr(key)} `;
}

